	old := now.Add(-48 * time.Hour)
	for _, path := range []string{
		oldSnapshot,
		oldGeneration,
		filepath.Join(brainDir, filepath.FromSlash(manifest.Sources.Semantic.GenerationPath)),
	} {
		if err := os.Chtimes(path, old, old); err != nil {
